#!/usr/bin/env node
/**
 * Generate the Tauri v2 updater manifest for a built bundle.
 *
 * `tauri build` only produces the `.sig` files - the `latest*.json` manifest
 * that the updater plugin fetches is normally generated by `tauri-action`.
 * This workflow builds each platform separately and does not use that action,
 * so the manifest is produced here instead.
 *
 * Usage:
 *   node scripts/make-updater-json.mjs --target windows --arch x86_64 \
 *        --tag v0.1.4 --installer src-tauri/target/release/bundle/nsis/DuckBridge_0.1.4_x64-setup.exe
 *
 * Writes `latest-<target>-<arch>.json` in the current directory.
 */
import fs from "node:fs";
import path from "node:path";

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i !== -1 && process.argv[i + 1] ? process.argv[i + 1] : fallback;
}

const target = arg("target");
const arch = arg("arch");
const tag = arg("tag");
const installer = arg("installer");

if (!target || !arch || !tag || !installer) {
  console.error(
    "usage: make-updater-json.mjs --target <windows|linux|darwin> --arch <x86_64|aarch64> --tag <v1.2.3> --installer <path>",
  );
  process.exit(2);
}

const confPath = path.resolve("src-tauri/tauri.conf.json");
const conf = JSON.parse(fs.readFileSync(confPath, "utf8"));
const version = conf.version;

const installerPath = path.resolve(installer);
const sigPath = `${installerPath}.sig`;
if (!fs.existsSync(sigPath)) {
  console.error(`signature not found: ${sigPath}`);
  console.error("build with TAURI_SIGNING_PRIVATE_KEY set to produce updater artifacts");
  process.exit(1);
}

const signature = fs.readFileSync(sigPath, "utf8").trim();
const repo = process.env.GITHUB_REPOSITORY || "MSNsoftware/DuckBridge";
const url = `https://github.com/${repo}/releases/download/${tag}/${path.basename(installerPath)}`;

const manifest = {
  version,
  notes: `DuckBridge ${version}`,
  pub_date: new Date().toISOString(),
  url,
  signature,
};

const out = `latest-${target}-${arch}.json`;
fs.writeFileSync(out, `${JSON.stringify(manifest, null, 2)}\n`);
console.log(`wrote ${out} -> ${url}`);
